<template><section class="settings-section"><b-alert :show="!!error" variant="danger">{{ error }}</b-alert><div v-if="!form" role="status">Loading farm settings…</div><template v-else>
<section class="settings-card"><div class="settings-card-title"><h6>Flag submission</h6><b-form-checkbox v-model="form.enabled" switch>Submission enabled</b-form-checkbox></div><div class="row">
<b-form-group class="col-md-4" label="Protocol" label-for="farm-protocol"><b-form-select id="farm-protocol" v-model="form.protocol" :options="[{value:'ructf_http',text:'RuCTF HTTP (default)'},{value:'forcad',text:'ForcAD HTTP'},{value:'volga',text:'Volga API v1'}]"/></b-form-group>
<b-form-group class="col-md-8" label="Scoreboard address / submission URL" label-for="farm-url" :description="form.protocol==='volga'?'Base API URL, e.g. https://board/api/flag/v1':'Full flag submission URL, e.g. http://10.10.10.10:8080/flags'"><b-form-input id="farm-url" v-model.trim="form.url" placeholder="http://10.10.10.10:8080/flags"/></b-form-group>
<b-form-group class="col-md-6" label="X-Team-Token" label-for="farm-token" :description="form.tokenSet?'Token saved. Leave this field blank to keep it.':'Team token for RuCTF / ForcAD'"><b-form-input id="farm-token" type="password" autocomplete="new-password" v-model="form.token"/><b-form-checkbox v-if="form.tokenSet" v-model="form.clearToken">Remove saved token</b-form-checkbox></b-form-group>
<b-form-group class="col-md-6" label="Flag format (regex)" label-for="farm-regex"><b-form-input id="farm-regex" v-model="form.flagFormat"/></b-form-group></div></section>
<section class="settings-card"><h6>Targets and exclusions</h6><div class="row"><b-form-group class="col-md-6" label="IP template" label-for="farm-pattern" description="{n} is replaced with the team number; leave blank to use manual targets only"><b-form-input id="farm-pattern" v-model.trim="form.pattern" placeholder="10.60.{n}.3"/></b-form-group><b-form-group class="col-md-3" label="First team" label-for="farm-first"><b-form-input id="farm-first" type="number" v-model.number="form.first"/></b-form-group><b-form-group class="col-md-3" label="Last team" label-for="farm-last"><b-form-input id="farm-last" type="number" v-model.number="form.last"/></b-form-group>
<b-form-group class="col-md-6" label="Additional targets: name = IP, one per line" label-for="farm-targets"><b-form-textarea id="farm-targets" v-model="targets" rows="4" placeholder="Team extra = 10.60.70.3"/></b-form-group><b-form-group class="col-md-6" label="Exclude IPs (including your own team)" label-for="farm-exclude"><b-form-textarea id="farm-exclude" v-model="exclude" rows="4" placeholder="10.60.1.3"/></b-form-group></div><b-button size="sm" variant="outline-secondary" @click="preview">Preview targets</b-button><div v-if="previewTargets" class="mt-2 small">{{ previewTargets.length }} targets: {{ previewTargets.map(t=>t.name+' · '+t.host).join(', ') }}</div></section>
<section class="settings-card"><h6>Queue and client</h6><div class="row"><b-form-group v-for="f in numbers" :key="f.key" class="col-md-4" :label="f.label" :label-for="'farm-'+f.key"><b-form-input :id="'farm-'+f.key" type="number" :min="f.min" :max="f.max" v-model.number="form[f.key]"/></b-form-group></div></section>
<div class="settings-footer"><span role="status">{{ saved?'Farm settings saved':'' }}</span><b-button variant="primary" :disabled="saving" @click="save">{{ saving?'Saving…':'Save farm settings' }}</b-button></div></template></section></template>
<script>
export default {
 data:()=>({form:null,targets:'',exclude:'',previewTargets:null,error:'',saved:false,saving:false,numbers:[{key:'period',label:'Submission interval, s',min:1,max:300},{key:'batch',label:'Flags per interval',min:1,max:100},{key:'lifetime',label:'Flag lifetime, s',min:10,max:86400},{key:'retention',label:'History retention, s',min:10,max:2592000},{key:'timeout',label:'Request / exploit timeout, s',min:1,max:30},{key:'clientInterval',label:'Exploit interval, s',min:1,max:3600},{key:'clientWorkers',label:'Parallel targets per client',min:1,max:64}]}),
 mounted(){this.load()},methods:{
 async load(){try{this.form=(await this.$http.get('/v2/farm/settings')).data;this.targets=this.form.targets.map(t=>t.name+' = '+t.host).join('\n');this.exclude=this.form.exclude.join('\n')}catch(e){this.error=e.response?.data?.error||e.message}},
 body(){return {...this.form,targets:this.targets.split('\n').filter(x=>x.trim()).map(x=>{const parts=x.split('=');if(parts.length!==2)throw Error('Targets: name = IP');return {name:parts[0].trim(),host:parts[1].trim()}}),exclude:this.exclude.split(/[\s,]+/).filter(Boolean)}},
 async preview(){this.error='';try{this.previewTargets=(await this.$http.post('/v2/farm/targets/preview',this.body())).data}catch(e){this.error=e.response?.data?.error||e.message}},
 async save(){this.error='';this.saved=false;this.saving=true;try{this.form=(await this.$http.put('/v2/farm/settings',this.body())).data;this.saved=true}catch(e){this.error=e.response?.data?.error||e.message}finally{this.saving=false}},
 }};
</script>
